// Layer 0 (game-free): the Xenos EDRAM model our renderer uses - render target formats and storage classes, surface
// pitch in tiles, and the byte address of a pixel's sample inside the 10 MB EDRAM. Plain CPU code, no GPU.
//
// Behaviour follows Xenia Canary e6cd2e4 (src/xenia/gpu/xenos.h, shaders/edram.xesli, draw_util.cc
// GetResolveEdramTileSpan; BSD-3-Clause, Copyright (c) Ben Vanik and Xenia project contributors) and rexglue SDK 0.10.0
// (include/rex/graphics/xenos.h). Re-expressed here; tests/layer0_renderer_core_test.cpp checks it against golden tables
// generated by running the reference code (tools/golden/gn_renderer_core_golden.cpp).
//
// Two things the references do not settle (see notes/42 and the S3.5 report):
//  - How the 4x/2x MSAA samples of a pixel are arranged in the single-sampled view. Canary e6cd2e4 interleaves pairs of
//    pixels (SampleLayout::kCanaryInterleaved); the rexglue SDK we build against and older Xenia put a pixel's samples
//    side by side (SampleLayout::kAdjacent). Both are here; the layout only matters where a game aliases an MSAA
//    surface with a different sample count, which Gears does with its half-pitch 4x clear (notes/35).
//  - How 64bpp samples are really stored. Both references use 40x16 64bpp samples per tile as a convention.
#pragma once

#include <algorithm>
#include <cstdint>

namespace xenos::edram {

constexpr uint32_t kTileWidthSamples = 80;
constexpr uint32_t kTileHeightSamples = 16;
constexpr uint32_t kTileDwords = kTileWidthSamples * kTileHeightSamples;  // 1280
constexpr uint32_t kTileBytes = kTileDwords * 4;                           // 5120
constexpr uint32_t kTileCount = 2048;
constexpr uint32_t kSizeBytes = kTileCount * kTileBytes;  // 10 MiB
constexpr uint32_t kBaseTilesBits = 11;
constexpr uint32_t kResolveAlignmentPixels = 8;

enum class Msaa : uint32_t { k1X = 0, k2X = 1, k4X = 2 };

enum class ColorFormat : uint32_t {
  k_8_8_8_8 = 0,
  k_8_8_8_8_GAMMA = 1,
  k_2_10_10_10 = 2,
  k_2_10_10_10_FLOAT = 3,  // 7e3 RGB, unorm alpha
  k_16_16 = 4,             // fixed point -32...32
  k_16_16_16_16 = 5,
  k_16_16_FLOAT = 6,
  k_16_16_16_16_FLOAT = 7,
  k_2_10_10_10_AS_10_10_10_10 = 10,
  k_2_10_10_10_FLOAT_AS_16_16_16_16 = 12,  // same bits as 7e3; higher blending precision only
  k_32_FLOAT = 14,
  k_32_32_FLOAT = 15,
};
enum class DepthFormat : uint32_t { kD24S8 = 0, kD24FS8 = 1 };

constexpr bool IsValidColorFormat(uint32_t f) {
  return f <= 7 || f == 10 || f == 12 || f == 14 || f == 15;
}
constexpr bool Is64bpp(ColorFormat f) {
  return f == ColorFormat::k_16_16_16_16 || f == ColorFormat::k_16_16_16_16_FLOAT || f == ColorFormat::k_32_32_FLOAT;
}
// The format with the same bits in memory, without the blending-precision variants (D29: one storage for both).
constexpr ColorFormat StorageFormat(ColorFormat f) {
  return f == ColorFormat::k_2_10_10_10_AS_10_10_10_10         ? ColorFormat::k_2_10_10_10
         : f == ColorFormat::k_2_10_10_10_FLOAT_AS_16_16_16_16 ? ColorFormat::k_2_10_10_10_FLOAT
                                                               : f;
}

// Width of one surface row in EDRAM tiles (80 samples wide; 4x MSAA doubles the samples per row; 64bpp doubles tiles).
constexpr uint32_t SurfacePitchTiles(uint32_t pitch_pixels, Msaa msaa, bool is_64bpp) {
  const uint32_t samples = pitch_pixels << uint32_t(msaa >= Msaa::k4X);
  const uint32_t tiles = (samples + (kTileWidthSamples - 1)) / kTileWidthSamples;
  return is_64bpp ? tiles << 1 : tiles;
}

// 24-bit unorm depth to float, exactly as D3D (0xFFFFFF -> 1.0, 0xC00000 -> 0.75).
constexpr float UNorm24To32(uint32_t n24) { return float(n24 + (n24 >> 23)) * (1.0f / float(1u << 24)); }

enum class SampleLayout : uint32_t {
  kCanaryInterleaved,  // Canary e6cd2e4 edram.xesli
  kAdjacent,           // rexglue SDK ROV path / older Xenia: a pixel's samples in its own 2x2 (4x) or 1x2 (2x) block,
                       // sample bit 0 vertical, bit 1 horizontal (samples at +0, +1 row, +1 column, +1 row +1 column)
};

struct SampleCoord {
  uint32_t u, v;
};

// Coordinates of sample `sample` of pixel (x, y) in the single-sampled view of the allocation.
// kCanaryInterleaved: 4x sample bit 0 is horizontal, bit 1 vertical; Canary's 2x formula is kept as written, which puts
// the 2x sample bit in u and the pixel's x bit 1 in v. kAdjacent: taken from the SDK ROV comments ("samples are at +0,
// +80, +1, +81" dwords; Xenia 4x sample 1 = bottom-left), not from running it.
constexpr SampleCoord GuestSample(uint32_t x, uint32_t y, uint32_t sample, Msaa msaa, SampleLayout layout) {
  if (layout == SampleLayout::kCanaryInterleaved) {
    if (msaa >= Msaa::k4X) {
      return {((x & ~1u) << 1) | (x & 1u) | ((sample & 1u) << 1), ((y & ~1u) << 1) | (y & 1u) | (sample & 2u)};
    }
    if (msaa == Msaa::k2X) {
      return {(x & ~2u) | ((sample & 1u) << 1), ((y & ~1u) << 1) | (y & 1u) | (x & 2u)};
    }
    return {x, y};
  }
  if (msaa >= Msaa::k4X) return {(x << 1) | ((sample >> 1) & 1u), (y << 1) | (sample & 1u)};
  if (msaa == Msaa::k2X) return {x, (y << 1) | (sample & 1u)};
  return {x, y};
}

struct AddressParams {
  uint32_t base_tiles = 0;
  uint32_t pitch_tiles = 0;  // from SurfacePitchTiles (already doubled for 64bpp)
  Msaa msaa = Msaa::k1X;
  bool is_depth = false;
  uint32_t format_ints_log2 = 0;  // 0 = 32bpp, 1 = 64bpp
  bool wrap = true;               // EDRAM addressing is periodic modulo 10 MiB
  uint32_t scale_x = 1, scale_y = 1;  // resolution scale (host pixels per guest pixel)
  SampleLayout layout = SampleLayout::kCanaryInterleaved;
};

// Byte address in EDRAM of sample `sample` of host pixel (px, py). Same steps as XeEdramOffsetBytes:
// tile = 80x16 samples at 32bpp (40x16 at 64bpp); depth swaps the two 40-sample halves of each tile.
constexpr uint32_t OffsetBytes(uint32_t px, uint32_t py, uint32_t sample, const AddressParams& p) {
  const uint32_t pix_x = px / p.scale_x, pix_y = py / p.scale_y;
  const uint32_t sub_x = px - pix_x * p.scale_x, sub_y = py - pix_y * p.scale_y;
  const SampleCoord g = GuestSample(pix_x, pix_y, sample, p.msaa, p.layout);
  uint32_t sx = g.u * p.scale_x + sub_x;
  uint32_t sy = g.v * p.scale_y + sub_y;
  const uint32_t tile32_w = kTileWidthSamples * p.scale_x, tile32_h = kTileHeightSamples * p.scale_y;
  const uint32_t tile_w = tile32_w >> p.format_ints_log2, tile_h = tile32_h;
  const uint32_t tx = sx / tile_w, ty = sy / tile_h;
  const uint32_t base = p.base_tiles + ty * p.pitch_tiles + tx;
  sx -= tx * tile_w;
  sy -= ty * tile_h;
  if (p.is_depth) {
    const uint32_t half = tile_w >> 1;
    sx = sx >= half ? sx - half : sx + half;
  }
  uint32_t address = base * (tile32_w * tile32_h) + ((sy * tile_w + sx) << p.format_ints_log2);
  if (p.wrap) address %= tile32_w * tile32_h * kTileCount;
  return address << 2;
}

// Tiles touched by a resolve: from the resolve's EDRAM base (tiles), offset within the first tile (in 8-pixel units),
// width and height (in 8-pixel units). Same as draw_util GetResolveEdramTileSpan.
struct TileSpan {
  uint32_t base_tiles, row_length_used, rows;
};
constexpr TileSpan ResolveTileSpan(uint32_t base_tiles, uint32_t pitch_tiles, Msaa msaa, bool is_64bpp,
                                   uint32_t offset_x_div_8, uint32_t offset_y_div_8, uint32_t width_div_8,
                                   uint32_t height_div_8) {
  const uint32_t xs = 3 + uint32_t(msaa >= Msaa::k4X) + uint32_t(is_64bpp);
  const uint32_t x0 = (offset_x_div_8 << xs) / kTileWidthSamples;
  const uint32_t x1 = (((offset_x_div_8 + width_div_8) << xs) + (kTileWidthSamples - 1)) / kTileWidthSamples;
  const uint32_t ys = 3 + uint32_t(msaa >= Msaa::k2X);
  const uint32_t y0 = (offset_y_div_8 << ys) / kTileHeightSamples;
  const uint32_t y1 = (((offset_y_div_8 + height_div_8) << ys) + (kTileHeightSamples - 1)) / kTileHeightSamples;
  return {base_tiles + y0 * pitch_tiles + x0, x1 - x0, y1 - y0};
}

}  // namespace xenos::edram
